<template><el-card><h3>导入学号名单</h3><el-input v-model="ids" type="textarea" rows="6"/><el-button type="primary" @click="save">校验并添加名单</el-button><el-divider/><h3>导出</h3><el-button @click="download('students.txt')">当前届全部学号 TXT</el-button><el-button @click="download('delivered.txt')">当前届已交付 TXT</el-button></el-card></template><script setup>import{ref}from'vue';const emit=defineEmits(['message']);const ids=ref('');async function save(){const r=await fetch('/api/v1/roster',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({student_ids:ids.value.split(/\s+/).filter(Boolean)})});emit('message',r.ok?'名单已保存':'名单保存失败')}function download(x){location.href='/api/v1/exports/'+x}</script>